-- +goose StatementBegin
INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.71.0',
  '2026-08-05',
  'Чеки магазинов из почты превращаются в траты Finance',
  E'Пересылаете письмо магазина с заказом на выделенный адрес — приложение разбирает его и записывает трату в Finance: сумма, дата покупки, магазин, номер заказа, способ оплаты. Первый магазин — Yerevan City (письма «Order #… delivered»).\n\nПозиции чека видно в самом письме и на новой вкладке «Чеки», но в Finance уходит ОДНА трата на итог чека: поход в магазин — это одна трата, а не двадцать. Сумма берётся именно из итога: позиции магазин показывает по каталожным ценам, и с итогом они не сходятся (вес, скидки), а из кошелька уходит итог.\n\nПовторная пересылка того же заказа трату не удвоит. Разбор включается у адреса, там же выбираются категория и счёт списания. Письма, пришедшие до настройки, разбираются кнопкой прямо в письме.\n\nВозможность выдаётся персонально в Админке («Чеки магазинов → траты в Finance») и работает с финансами того аккаунта, которому принадлежит почтовый адрес.',
  E'Разбор — internal/receipts, разбирается ТЕКСТОВАЯ часть письма: вёрстка рассылок меняется от кампании к кампании, а текстовая версия у магазина годами одна и та же. Учтены оба вида пересылки: Gmail («---------- Forwarded message ---------») и Apple Mail (всё процитировано «> »); расцитирование снимает любое число уровней. Имя позиции жадное — разделитель « x » берётся последним, иначе «Item x 2 x 3 100.00֏» разобралось бы как количество 2 с единицей «x». Итоговые строки приходят и с пробелом («Total 16027.46֏»), и без («Total24656.22֏»). Неразрывные и узкие пробелы нормализуются: без этого числа не парсятся.\n\nБез номера заказа чек отклоняется — иначе нет защиты от повторного импорта. Идемпотентность двойная: unique (user_id, parser, order_no) на чеках и finance_transactions.external_id вида «yerevancity:3424178».\n\nДата траты — отдельная колонка purchased_on DATE, а не компоненты из purchased_at. Поймано при проверке: timestamptz читается в зоне сессии, и покупка в 23:23 по Еревану уезжала в трату следующего дня (чек от 25.02 записывался на 26.02).\n\nДоступ — механизм персональных опций (FeaturesRegistry + feature_access): код mail.receipts, админ проходит всегда. Проверено: письмо на адрес пользователя без опции принимается, но чек и трата НЕ создаются («разбор чеков не разрешён пользователю»); после выдачи опции в Админке разбор начинает работать, данные аккаунтов не смешиваются.\n\nМиграция 0089: mail_receipts + mail_receipt_items, три колонки разбора у mail_addresses. Импортёр вынесен в internal/receiptimport — он нужен и приёмнику почты, и кнопке «разобрать»; в main зависимости приёмника проставляются ДО запуска (иначе поле читалось бы из чужой горутины).\n\nПроверено на трёх настоящих письмах: 11, 7 и 8 позиций, суммы, даты, способ оплаты, повторная пересылка не удваивает трату, ручной разбор уже разобранного → 409, баланс счёта сходится до копейки. Тесты парсера на синтетических письмах: в репозитории публикуется снапшот, настоящим именам, телефонам и адресам там не место.'
);
-- +goose StatementEnd

